 '<table style="width:100%;border-collapse:collapse"><tr style="background:#eef2f8;color:#475467;font-size:15px;text-transform:uppercase;letter-spacing:.06em"><th style="text-align:left;padding:12px 16px">Client</th><th style="text-align:left">Date</th><th style="text-align:left">Gift</th><th style="text-align:right;padding-right:20px">Cost</th><th style="text-align:left">Response</th></tr>'
